-- Cook-Walden IABA map — initial data load (generated by scripts/export_seed.py)
-- Run AFTER supabase/schema.sql. Safe to re-run (upserts by id).

on conflict (id) do update set
  lot = excluded.lot,
  space = excluded.space,
  status = excluded.status,
  color = excluded.color,
  owner = excluded.owner,
  person_name = excluded.person_name,
  person_burial = excluded.person_burial;
